/*
====================================================================
ФАЙЛ: app.js
====================================================================

Этот файл содержит всю динамическую логику сайта.

Он отвечает за:
1. хранение сценарных событий;
2. создание карточек параметров;
3. появление сообщений по времени;
4. синхронное обновление параметров;
5. запуск, паузу, сброс и ускорение;
6. автопрокрутку и ручной скролл.

Главная идея:
каждое событие в массиве EVENTS может одновременно:
- вывести сообщение в чат;
- изменить один или несколько параметров справа.
====================================================================
*/

/*
--------------------------------------------------------------------
1. СЦЕНАРНЫЕ СОБЫТИЯ
--------------------------------------------------------------------

Каждый объект события содержит:

t:
  время появления сообщения в секундах;

type:
  визуальный тип сообщения;

agent:
  имя агента или управляющего узла;

text:
  текст сообщения;

params:
  необязательные изменения параметров справа.

Пример:

{
  t: 120,
  type: "warning",
  agent: "Агент диагностики и телеметрии",
  text: "Обнаружен перегрев.",
  params: {
    temp: {
      value: "+53 °C",
      sub: "кабельный канал",
      level: "danger"
    }
  }
}
*/
const EVENTS=[{"t": 0, "type": "system", "agent": "Система купола", "text": "Мультиагентное управление запущено. Все контуры доступны.", "params": {"mode": {"value": "Штатный", "level": "ok"}, "battery": {"value": "78%", "n": 78, "level": "ok"}, "power": {"value": "2,4 кВт", "sub": "генерация", "level": "ok"}, "load": {"value": "1,47 кВт", "sub": "потребление", "level": "ok"}, "air": {"value": "720 ppm", "sub": "CO₂", "level": "ok"}, "temp": {"value": "+21 °C", "sub": "внутри", "level": "ok"}, "link": {"value": "ONLINE", "sub": "основной канал", "level": "ok"}, "production": {"value": "ГОТОВ", "sub": "3D + CNC", "level": "ok"}}}, {"t": 18, "type": "agent", "agent": "Агент энергетического контура", "text": "Профицит около 0,9 кВт. Батарея заряжается, ограничивать линии не требуется.", "params": {"battery": {"value": "79%", "n": 79, "level": "ok"}, "power": {"value": "2,4 кВт", "sub": "генерация", "level": "ok"}}}, {"t": 36, "type": "agent", "agent": "Агент диагностики и телеметрии", "text": "Инвертор — 40 °C, распределительный щит — 33 °C. Аномальных токов нет.", "params": {"temp": {"value": "+21 °C", "sub": "внутри · стабильно", "level": "ok"}}}, {"t": 54, "type": "agent", "agent": "Агент производственного контура", "text": "3D-принтер и фрезер готовы. Производственная линия свободна.", "params": {"production": {"value": "ГОТОВ", "sub": "очередь пуста", "level": "ok"}}}, {"t": 72, "type": "agent", "agent": "Агент связи с внешним миром", "text": "Эмулируемый основной канал устойчив. Прогноз: усиление порывов ветра.", "params": {"link": {"value": "ONLINE", "sub": "190 мс", "level": "ok"}}}, {"t": 92, "type": "decision", "agent": "Агент-координатор купола", "text": "Штатный аккорд подтверждён: энергия, производство, связь и телеметрия согласованы.", "params": {"mode": {"value": "Штатный", "level": "ok"}}}, {"t": 118, "type": "warning", "agent": "Агент диагностики и телеметрии", "text": "Зафиксирован механический импульс. Генерация солнечного контура падает.", "params": {"power": {"value": "0,6 кВт", "sub": "генерация ↓", "level": "danger"}, "mode": {"value": "Авария 1", "level": "danger"}}}, {"t": 135, "type": "agent", "agent": "Агент энергетического контура", "text": "Возник дефицит 0,8 кВт. Текущая конфигурация быстро разряжает батарею.", "params": {"load": {"value": "1,47 кВт", "sub": "выше генерации", "level": "warn"}, "battery": {"value": "77%", "n": 77, "level": "warn"}}}, {"t": 152, "type": "agent", "agent": "Агент связи с внешним миром", "text": "Облачность исключена. Провалы совпадают с порывами ветра.", "params": {"link": {"value": "ONLINE", "sub": "контекст получен", "level": "ok"}}}, {"t": 170, "type": "agent", "agent": "Агент диагностики и телеметрии", "text": "Вероятность механически нестабильного соединения солнечной панели — 0,88.", "params": {"power": {"value": "0,6–1,1", "sub": "кВт · нестабильно", "level": "danger"}}}, {"t": 192, "type": "decision", "agent": "Агент-координатор купола", "text": "Аккорд собран: отключаем производство, освещение переводим в экономичный режим, телеметрию сохраняем.", "params": {"production": {"value": "ОТКЛ.", "sub": "снята нагрузка", "level": "muted"}, "mode": {"value": "Стабилизация", "level": "warn"}}}, {"t": 208, "type": "result", "agent": "Узел управления энергетическим контуром", "text": "Производственную линию отключил. Общая нагрузка снизилась до 1,06 кВт.", "params": {"load": {"value": "1,06 кВт", "sub": "после отключения", "level": "ok"}, "production": {"value": "ОТКЛ.", "sub": "3D + CNC", "level": "muted"}}}, {"t": 226, "type": "result", "agent": "Узел управления энергетическим контуром", "text": "Освещение переведено в экономичный режим. Рабочие зоны сохранены.", "params": {"load": {"value": "0,91 кВт", "sub": "экономичный режим", "level": "ok"}}}, {"t": 250, "type": "agent", "agent": "Агент энергетического контура", "text": "Автономность без солнечной генерации — 5 часов 40 минут.", "params": {"battery": {"value": "75%", "n": 75, "level": "warn"}, "mode": {"value": "Устойчивый", "level": "warn"}}}, {"t": 280, "type": "decision", "agent": "Агент-координатор купола", "text": "Первый кризис стабилизирован организационно: система перестроена вокруг недоступной функции.", "params": {"mode": {"value": "Ограниченно устойчивый", "level": "warn"}}}, {"t": 318, "type": "telemetry", "agent": "Энергетический контур", "text": "Генерация кратковременно восстановилась до 1,8 кВт.", "params": {"power": {"value": "1,8 кВт", "sub": "60 с стабильно", "level": "ok"}}}, {"t": 340, "type": "agent", "agent": "Агент производственного контура", "text": "Готов к пробной печати фиксатора с лимитом 320 Вт.", "params": {"production": {"value": "ГОТОВ", "sub": "лимит 320 Вт", "level": "warn"}}}, {"t": 362, "type": "decision", "agent": "Агент-координатор купола", "text": "Разрешаю пробный запуск 3D-принтера. Фрезер остаётся отключён.", "params": {"production": {"value": "3D ON", "sub": "CNC OFF", "level": "warn"}, "load": {"value": "1,28 кВт", "sub": "с лимитом", "level": "warn"}}}, {"t": 396, "type": "warning", "agent": "Агент диагностики и телеметрии", "text": "Ток производственной линии вырос до 6,4 А. Кабельный канал нагрелся до 53 °C.", "params": {"temp": {"value": "+53 °C", "sub": "кабельный канал", "level": "danger"}, "production": {"value": "РИСК", "sub": "перегрев линии", "level": "danger"}}}, {"t": 418, "type": "agent", "agent": "Агент производственного контура", "text": "Останавливаю технологический план. Деталь больше не приоритет.", "params": {"production": {"value": "СТОП", "sub": "задача отменена", "level": "danger"}}}, {"t": 438, "type": "danger", "agent": "Агент диагностики и телеметрии", "text": "Кризис 2. Признаки указывают на повреждение изоляции производственной линии.", "params": {"mode": {"value": "Авария 2", "level": "danger"}}}, {"t": 456, "type": "decision", "agent": "Агент-координатор купола", "text": "Аккорд однозначен: производство отказывается от задачи, диагностика подтверждает риск, энергетика изолирует контур.", "params": {"production": {"value": "ИЗОЛЯЦИЯ", "sub": "аварийное отключение", "level": "danger"}}}, {"t": 472, "type": "result", "agent": "Узел управления энергетическим контуром", "text": "Производственную линию отключил. Ток исчез. Нагрузка снизилась до 0,88 кВт.", "params": {"load": {"value": "0,88 кВт", "sub": "стабильно", "level": "ok"}, "production": {"value": "ОТКЛ.", "sub": "повторный запуск запрещён", "level": "muted"}}}, {"t": 500, "type": "telemetry", "agent": "Агент диагностики и телеметрии", "text": "Температура снижается: 53 → 37 °C. Нового роста нет.", "params": {"temp": {"value": "+37 °C", "sub": "снижается", "level": "warn"}}}, {"t": 530, "type": "agent", "agent": "Агент связи с внешним миром", "text": "Аварийный пакет принят условным центром управления.", "params": {"link": {"value": "ДОСТАВЛЕНО", "sub": "аварийный пакет", "level": "ok"}}}, {"t": 558, "type": "agent", "agent": "Агент энергетического контура", "text": "Заряд — 72%. Прогноз автономной работы — 6 часов 10 минут.", "params": {"battery": {"value": "72%", "n": 72, "level": "warn"}}}, {"t": 582, "type": "decision", "agent": "Агент-координатор купола", "text": "Новый устойчивый режим сформирован: без производства и без гарантированной солнечной генерации.", "params": {"mode": {"value": "Ограниченно устойчивый", "level": "warn"}}}, {"t": 600, "type": "system", "agent": "Купол", "text": "Сценарий завершён. Автономность сохранена ценой отказа от части функций.", "params": {"mode": {"value": "Завершено", "level": "ok"}}}];
/*
--------------------------------------------------------------------
2. SVG-ИКОНКИ
--------------------------------------------------------------------
Иконки хранятся как строки SVG.
Отдельные файлы изображений не требуются.
*/
const ICONS={"mode": "<svg viewBox=\"0 0 24 24\"><path d=\"M12 3a9 9 0 1 0 9 9\"/><path d=\"M12 7v5l3 2\"/><path d=\"M17 3h4v4\"/></svg>", "battery": "<svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"7\" width=\"17\" height=\"10\" rx=\"2\"/><path d=\"M20 10h2v4\"/><path d=\"M7 10v4M11 10v4M15 10v4\"/></svg>", "power": "<svg viewBox=\"0 0 24 24\"><path d=\"m13 2-8 12h7l-1 8 8-12h-7z\"/></svg>", "load": "<svg viewBox=\"0 0 24 24\"><path d=\"M4 19h16\"/><path d=\"M6 16V8M10 16V5M14 16v-6M18 16V3\"/></svg>", "air": "<svg viewBox=\"0 0 24 24\"><path d=\"M3 8h11a3 3 0 1 0-3-3\"/><path d=\"M3 12h16a3 3 0 1 1-3 3\"/><path d=\"M3 16h8\"/></svg>", "temp": "<svg viewBox=\"0 0 24 24\"><path d=\"M14 14.8V5a4 4 0 0 0-8 0v9.8a6 6 0 1 0 8 0Z\"/><path d=\"M10 7v9\"/></svg>", "link": "<svg viewBox=\"0 0 24 24\"><path d=\"M5 12.6a10 10 0 0 1 14 0\"/><path d=\"M8.5 16a5 5 0 0 1 7 0\"/><circle cx=\"12\" cy=\"20\" r=\"1\"/></svg>", "production": "<svg viewBox=\"0 0 24 24\"><path d=\"M4 20h16\"/><path d=\"M6 20V8l5 3V8l7 4v8\"/><path d=\"M8 5h3v3H8z\"/><path d=\"M15 15h2\"/></svg>"};
/*
--------------------------------------------------------------------
3. НАЗВАНИЯ КАРТОЧЕК
--------------------------------------------------------------------
Ключи должны совпадать с ключами параметров в EVENTS.
*/
const LABELS={"mode": "Режим системы", "battery": "Батарея", "power": "Генерация", "load": "Потребление", "air": "Состав воздуха", "temp": "Температура", "link": "Связь", "production": "Производство"};
/*
--------------------------------------------------------------------
4. ПОРЯДОК КАРТОЧЕК
--------------------------------------------------------------------
Порядок элементов в массиве определяет расположение карточек.
*/
const KEYS=["mode","battery","power","load","air","temp","link","production"];
/*
--------------------------------------------------------------------
5. НАЧАЛЬНЫЕ ЗНАЧЕНИЯ
--------------------------------------------------------------------
Используются до появления первого события и после сброса.
*/
const defaults={
 mode:{value:"—",level:"muted"},battery:{value:"—",n:0,level:"muted"},power:{value:"—",level:"muted"},load:{value:"—",level:"muted"},
 air:{value:"—",level:"muted"},temp:{value:"—",level:"muted"},link:{value:"—",level:"muted"},production:{value:"—",level:"muted"}
};
/*
--------------------------------------------------------------------
6. СОСТОЯНИЕ ПРОИГРЫВАТЕЛЯ
--------------------------------------------------------------------

state:
  актуальные параметры купола;

elapsed:
  прошедшее сценарное время;

shown:
  количество уже показанных событий;

playing:
  запущен ли сценарий;

autoScroll:
  нужно ли автоматически прокручивать чат вниз.
*/
let state=structuredClone(defaults),elapsed=0,shown=0,playing=false,last=null,raf=null,autoScroll=true;
const DURATION=600,$=id=>document.getElementById(id),chat=$("chat");

/*
--------------------------------------------------------------------
7. ФОРМАТИРОВАНИЕ ВРЕМЕНИ
--------------------------------------------------------------------
Преобразует секунды в строку формата ММ:СС.
*/
function fmt(s){s=Math.floor(Math.max(0,Math.min(DURATION,s)));return String(Math.floor(s/60)).padStart(2,"0")+":"+String(s%60).padStart(2,"0")}
/*
--------------------------------------------------------------------
8. СОЗДАНИЕ КАРТОЧЕК
--------------------------------------------------------------------
Карточки параметров создаются автоматически по массиву KEYS.
Поэтому их не нужно вручную прописывать в index.html.
*/
function buildCards(){
 const box=$("cards");box.innerHTML="";
 KEYS.forEach(k=>{
  const c=document.createElement("article");c.className="param muted";c.id="param-"+k;
  c.innerHTML=`<div class="param-top"><div class="icon">${ICONS[k]}</div><div class="param-label">${LABELS[k]}</div></div>
  <div class="value" id="value-${k}">—</div><div class="sub" id="sub-${k}">ожидание данных</div>
  ${k==="battery"?'<div class="meter"><div id="meter-battery"></div></div>':""}`;
  box.appendChild(c);
 });
}
/*
--------------------------------------------------------------------
9. ОБНОВЛЕНИЕ ПАРАМЕТРА
--------------------------------------------------------------------

k:
  ключ карточки, например battery или temp;

next:
  новые данные параметра.

Функция:
- сохраняет новое состояние;
- меняет текст;
- меняет цвет;
- обновляет шкалу батареи;
- запускает короткую анимацию.
*/
function updateParam(k,next){
 state[k]={...state[k],...next};
 const c=$("param-"+k),v=$("value-"+k),s=$("sub-"+k);
 c.className="param "+(state[k].level||"muted")+" changed";
 v.textContent=state[k].value??"—";s.textContent=state[k].sub??"";
 if(k==="battery") $("meter-battery").style.width=(state[k].n??0)+"%";
 setTimeout(()=>c.classList.remove("changed"),560);
}
/*
--------------------------------------------------------------------
10. ПОДПИСЬ ТИПА СООБЩЕНИЯ
--------------------------------------------------------------------
Преобразует внутренний тип в понятную русскую метку.
*/
function tagName(type){
 return ({agent:"АГЕНТ",telemetry:"ТЕЛЕМЕТРИЯ",warning:"ПРЕДУПРЕЖДЕНИЕ",danger:"АВАРИЯ",decision:"АККОРД / РЕШЕНИЕ",result:"ИСПОЛНЕНО",system:"СИСТЕМА"})[type]||type;
}
/*
--------------------------------------------------------------------
11. ДОБАВЛЕНИЕ СОБЫТИЯ
--------------------------------------------------------------------
Одновременно:
- создаёт сообщение слева;
- обновляет параметры справа;
- решает, нужно ли прокрутить чат вниз.
*/
function addEvent(e){
 const near=chat.scrollHeight-chat.scrollTop-chat.clientHeight<90;
 const row=document.createElement("div");row.className="msg";row.dataset.type=e.type;
 row.innerHTML=`<div class="msg-time">${fmt(e.t)}</div><div class="bubble"><div class="meta"><span class="tag">${tagName(e.type)}</span><span class="agent">${e.agent}</span></div><div class="text">${e.text}</div></div>`;
 chat.appendChild(row);
 Object.entries(e.params||{}).forEach(([k,v])=>updateParam(k,v));
 if(autoScroll&&near) chat.scrollTop=chat.scrollHeight; else $("jump").style.display="block";
}
/*
--------------------------------------------------------------------
12. ГЛАВНЫЙ ЦИКЛ
--------------------------------------------------------------------
requestAnimationFrame вызывает эту функцию перед перерисовкой экрана.

Алгоритм:
1. вычислить, сколько реального времени прошло;
2. умножить его на выбранную скорость;
3. увеличить сценарное время;
4. показать события, время которых наступило;
5. обновить шкалу времени;
6. запросить следующий кадр.
*/
function tick(now){
 if(!playing)return;if(last===null)last=now;
 elapsed+=(now-last)/1000*Number($("speed").value);last=now;
 while(shown<EVENTS.length&&EVENTS[shown].t<=elapsed)addEvent(EVENTS[shown++]);
 $("clock").textContent=fmt(elapsed);$("track").style.width=Math.min(100,elapsed/DURATION*100)+"%";$("status").textContent="сценарий выполняется";
 if(elapsed>=DURATION){playing=false;elapsed=DURATION;$("status").textContent="сценарий завершён";$("play").textContent="▶ Повторить";return}
 raf=requestAnimationFrame(tick);
}
/*
--------------------------------------------------------------------
13. СБРОС СЦЕНАРИЯ
--------------------------------------------------------------------
Очищает чат, возвращает время к нулю
и восстанавливает начальные значения.
*/
function reset(){
 if(raf)cancelAnimationFrame(raf);state=structuredClone(defaults);elapsed=0;shown=0;playing=false;last=null;autoScroll=true;
 chat.innerHTML="";$("clock").textContent="00:00";$("track").style.width="0%";$("status").textContent="готов к запуску";$("jump").style.display="none";$("play").textContent="▶ Запустить";
 buildCards();KEYS.forEach(k=>updateParam(k,defaults[k]));
}
/*
--------------------------------------------------------------------
14. КНОПКИ УПРАВЛЕНИЯ
--------------------------------------------------------------------
Ниже назначаются обработчики запуска, паузы и сброса.
*/
$("play").onclick=()=>{if(elapsed>=DURATION)reset();if(!playing){playing=true;last=null;$("play").textContent="▶ Идёт";raf=requestAnimationFrame(tick)}};
$("pause").onclick=()=>{playing=false;last=null;$("status").textContent="пауза";$("play").textContent="▶ Продолжить";if(raf)cancelAnimationFrame(raf)};
$("reset").onclick=reset;
$("jump").onclick=()=>{chat.scrollTo({top:chat.scrollHeight,behavior:"smooth"});autoScroll=true;$("jump").style.display="none"};
/*
--------------------------------------------------------------------
15. РУЧНОЙ СКРОЛЛ
--------------------------------------------------------------------
Если пользователь листает историю вверх,
автопрокрутка отключается.
*/
chat.addEventListener("scroll",()=>{const near=chat.scrollHeight-chat.scrollTop-chat.clientHeight<90;if(!near)autoScroll=false;else $("jump").style.display="none"});
chat.addEventListener("wheel",()=>{autoScroll=false},{passive:true});
reset();